from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    current = []
    balance = 0

    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            if balance == 0 and current:
                groups.append(''.join(current))
                current = []
            current.append(char)
            balance += 1
        elif char == ')':
            current.append(char)
            balance -= 1

        if balance < 0:
            raise ValueError("Unbalanced parentheses")

        if balance == 0 and current:
            groups.append(''.join(current))
            current = []

    if balance != 0:
        raise ValueError("Unbalanced parentheses")

    return groups

